terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

resource "aws_iam_user" "basic_user_1" {
  name = "basic-user-1"

  tags = {
    Name        = "basic-user-1"
    Environment = "basic"
  }
}

resource "aws_iam_user" "basic_user_2" {
  name = "basic-user-2"

  tags = {
    Name        = "basic-user-2"
    Environment = "basic"
